head.script:
scwin.keydownE = function(e) {
    console.log("keydown");
    var evt = e || event;
    scwin.stop_event(evt);
    return false;
};
scwin.keyupE = function(e) {
    console.log("keyup");
    var evt = e || event;
    stop_event1(evt);
    return false;
};
scwin.stop_event = function(e) {
    var evt = e || event;
    debugger;
    if (evt) {
        evt.stopPropagation();
        evt.preventDefault();
        evt.initEvent;
    }
};
scwin.dont_event = function(flag) {
    if (flag) {
        document.addEventListener("keydown", keydownE, false);
        document.addEventListener("keyup", keyupE, false);
    } else {
        document.removeEventListener("keydown", keydownE, false);
        document.removeEventListener("keyup", keyupE, false);
    }
};
scwin.btn_test_onclick = function(e) {
    WebSquare.layer.showProcessMessage("프로세스메세지 처리");
    input1.focus();
    //dont_event(true);
    setTimeout(function() {
        WebSquare.layer.hideProcessMessage();
        //dont_event(false);
    }, 2000);
};
scwin.btn_test2_onclick = function(e) {
    WebSquare.layer.showProcessMessage("프로세스메세지 처리");
    gridView1.setFocusedCell(1, 1, true);
    // scwin.dont_event(true);
    setTimeout(function() {
        WebSquare.layer.hideProcessMessage();
        //dont_event(false);
    }, 2000);
};
scwin.input1_onkeydown = function(e) {
    console.log(e.keyCode);
    var keycode = e.keyCode;
    if (keycode == 13) {
        WebSquare.layer.showProcessMessage("프로세스메세지 처리");
        gridView1.setFocusedCell(1, 1, true);
        scwin.dont_event(true);
        setTimeout(function() {
            WebSquare.layer.hideProcessMessage();
            scwin.dont_event(false);
        }, 2000);
    }
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
